from __future__ import annotations

import re
from datetime import date

from fastapi.responses import HTMLResponse

from .web import dashboard_html


_NEW_CARD = '''<div class="card" id="surebet-section"><div class="section-title"><h2>💰 SUREBET · CENTRO ÚNICO</h2><span class="eyebrow">Oportunidades + cálculo automático</span></div><p class="muted">La calculadora aparece únicamente cuando existe una surebet válida. Las cuotas se redistribuyen automáticamente para aprovechar el arbitraje.</p><div class="surebet-scope"><button id="scope-peru" onclick="setSurebetScope('peru')">🇵🇪 PERÚ</button><button id="scope-world" onclick="setSurebetScope('world')">🌎 MUNDIAL</button><button id="scope-all" onclick="setSurebetScope('all')">🌐 TODO</button></div><div class="surebet-buttons"><button id="surebet-pre-button" onclick="loadSurebetPre()">📅 SUREBET PRE-PARTIDO</button><button id="surebet-live-button" class="live-button" onclick="loadSurebetLive()">🔴 SUREBET LIVE · BUSCAR AHORA</button></div><div class="surebet-filters"><label>LIGA <select id="surebet-league" onchange="applyLeagueFilter()"><option value="">TODAS LAS LIGAS</option></select></label></div><div class="status muted" id="surebet-status">Conecta OddsPapi para habilitar las búsquedas.</div><div id="surebet-summary" class="surebet-summary"></div><div id="surebet" class="muted">No hay búsqueda activa.</div></div>'''

_SUREBET_JS = r'''const SB={scope:'peru',data:null};
const sb$=id=>document.getElementById(id);
const escSB=v=>String(v??'').replace(/[&<>\'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function setSurebetScope(scope){SB.scope=scope;['peru','world','all'].forEach(x=>{const b=sb$('scope-'+x);if(b)b.classList.toggle('active',x===scope)});if(SB.data)renderSurebet(SB.data)}
function sbBusy(v){['surebet-pre-button','surebet-live-button'].forEach(id=>{const b=sb$(id);if(b)b.disabled=v})}
function scopeLabel(){return SB.scope==='peru'?'🇵🇪 PERÚ':SB.scope==='world'?'🌎 MUNDIAL':'🌐 TODO'}
function money(v){return 'S/ '+Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})}
function pct(v){return (Number(v||0)*100).toFixed(2)+'%'}
function calculator(o){const t=o.target_profits||{};const ks=[250,500,1000,3000];const has=ks.some(k=>t[k]||t[String(k)]);if(!has)return '';return `<div class="calc-title">🧮 CALCULADORA AUTOMÁTICA · GANANCIA GARANTIZADA</div><table class="calc-table"><thead><tr><th>Ganancia objetivo</th><th>Capital necesario</th><th>Retorno garantizado</th><th>Ganancia</th><th>ROI</th></tr></thead><tbody>${ks.map(k=>{const x=t[k]||t[String(k)];if(!x)return '';return `<tr><td><b>${money(k)}</b></td><td>${money(x.total_stake)}</td><td>${money(x.total_return)}</td><td class="profit">${money(x.guaranteed_profit)}</td><td>${Number(x.roi_percent||0)}%</td></tr>`}).join('')}</tbody></table><div class="calc-title">💵 DISTRIBUCIÓN AUTOMÁTICA · PARA GANAR ${money(250)}</div><table class="stake-table"><thead><tr><th>Resultado</th><th>Casa</th><th>Cuota</th><th>Apostar</th></tr></thead><tbody>${Object.entries(o.outcomes||{}).map(([s,q])=>`<tr><td>${escSB(s)}</td><td>${escSB(q.bookmaker)}</td><td><b>${q.odds}</b></td><td><b>${money(((t[250]||t['250']).stakes||{})[s])}</b></td></tr>`).join('')}</tbody></table>`}
function renderSurebet(d){SB.data=d;const box=sb$('surebet'),summary=sb$('surebet-summary'),sel=sb$('surebet-league');let rows=Array.isArray(d.opportunities)?d.opportunities.slice():[];const leagues=[...new Set(rows.map(x=>x.competition).filter(Boolean))].sort();const old=sel?.value;if(sel){sel.innerHTML='<option value="">TODAS LAS LIGAS</option>'+leagues.map(x=>`<option value="${escSB(x)}">${escSB(x)}</option>`).join('');if(leagues.includes(old))sel.value=old}if(sel?.value)rows=rows.filter(x=>String(x.competition||'').toLowerCase().includes(sel.value.toLowerCase()));summary.innerHTML=`<div class="metric"><span>ÁMBITO</span><b>${scopeLabel()}</b></div><div class="metric"><span>SUREBETS</span><b>${rows.length}</b></div><div class="metric"><span>MODO</span><b>${d.mode==='live'?'🔴 LIVE':'📅 PRE-MATCH'}</b></div>`;if(!rows.length){box.innerHTML='<div class="empty-surebet"><b>ℹ️ No hay surebet válida en este momento.</b><br>La calculadora permanece oculta hasta encontrar una oportunidad real.</div>';return}box.innerHTML=rows.map(o=>`<article class="surebet-opportunity"><div class="opp-head"><div><div class="eyebrow">${escSB(o.competition||'Liga no identificada')}</div><h3>${escSB(o.match)}</h3><span class="muted">${escSB(o.market)} · Línea ${escSB(o.line??'-')} · ${o.mode==='live'?'🔴 LIVE':'📅 PRE-MATCH'}</span></div><div class="margin-box"><small>MARGEN SUREBET</small><strong>${pct(o.profit_margin)}</strong></div></div><div class="odds-grid">${Object.entries(o.outcomes||{}).map(([s,q])=>`<div class="odd-card"><span>${escSB(s)}</span><b>${q.odds}</b><small>${escSB(q.bookmaker)}</small></div>`).join('')}</div><div class="calc-box">${calculator(o)}</div><div class="opp-footer"><span>Probabilidad implícita: <b>${pct(o.implied_sum)}</b> · Mezcla: <b>${escSB(o.bookmaker_mix||'-')}</b></span><button class="verify-button" onclick="verifySurebet(${o.match_id})">🔍 VERIFICAR CUOTAS AHORA</button></div></article>`).join('')}
async function sbJson(r){let d={};try{d=await r.json()}catch(_){ }if(!r.ok)throw new Error(d.detail||`HTTP ${r.status}`);return d}
async function loadSurebetPre(){sbBusy(true);sb$('surebet-status').textContent=`🔄 Revisando PRE-PARTIDO · ${scopeLabel()}...`;try{const p=new URLSearchParams({limit:'100',scope:SB.scope});const d=await sbJson(await fetch('/api/v1/arbitrage/pre-match?'+p,{cache:'no-store'}));sb$('surebet-status').textContent=`📅 PRE-PARTIDO · ${d.opportunities?.length||0} oportunidades · sin consulta nueva a OddsPapi.`;renderSurebet(d)}catch(e){sb$('surebet-status').textContent='❌ '+e.message}finally{sbBusy(false)}}
async function loadSurebetLive(){sbBusy(true);sb$('surebet-status').textContent=`🔄 BUSCAR AHORA · consultando LIVE · ${scopeLabel()}...`;sb$('surebet').innerHTML='<p>Actualizando cuotas live...</p>';try{const p=new URLSearchParams({limit:'100',hours:'1',scope:SB.scope});const d=await sbJson(await fetch('/api/v1/arbitrage/live?'+p,{method:'POST',cache:'no-store'}));sb$('surebet-status').textContent=`🔴 LIVE actualizado · ${d.sync?.live_matches_seen||0} partidos · ${d.sync?.odds_saved||0} cuotas · ${d.opportunities?.length||0} surebets.`;renderSurebet(d)}catch(e){sb$('surebet-status').textContent='❌ '+e.message}finally{sbBusy(false)}}
async function verifySurebet(id){sb$('surebet-status').textContent='🔍 Verificando nuevamente las cuotas...';try{const p=new URLSearchParams({limit:'100',scope:SB.scope});const d=await sbJson(await fetch(`/api/v1/arbitrage/verify/${id}?`+p,{method:'POST',cache:'no-store'}));sb$('surebet-status').textContent=d.surebet_confirmed?'✅ SUREBET CONFIRMADA · las cuotas siguen permitiendo arbitraje.':'⚠️ LA SUREBET DESAPARECIÓ · las cuotas cambiaron.';renderSurebet(d)}catch(e){sb$('surebet-status').textContent='❌ '+e.message}}
function applyLeagueFilter(){if(SB.data)renderSurebet(SB.data)}
setSurebetScope('peru');'''

_RE = re.compile(r"function renderSurebet\(.*?async function loadFinal\(", re.S)


def dashboard_response(today: date) -> HTMLResponse:
    html = dashboard_html(today)
    # Replace the legacy Surebet block with the only Surebet control surface.
    html = re.sub(r'<div class="card" id="surebet-section">.*?<div id="surebet"[^>]*>.*?</div></div>', _NEW_CARD, html, count=1, flags=re.S)
    html = re.sub(r'<div class="card"><div class="section-title"><h2>💰 Surebet</h2>.*?<div id="surebet"[^>]*>.*?</div></div>', _NEW_CARD, html, count=1, flags=re.S)
    html = _RE.sub(_SUREBET_JS + 'async function loadFinal(', html, count=1)
    html = html.replace('.profit{font-weight:800}', '.profit{font-weight:800}.metric{background:#f4f6fa;border-radius:10px;padding:10px}.metric span{display:block;font-size:10px;color:#68758a;font-weight:800}.metric b{font-size:19px;display:block;margin-top:4px}.surebet-scope{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.surebet-scope button{border:1px solid #dfe5ee;border-radius:9px;padding:9px 12px;background:white;font-weight:800;cursor:pointer}.surebet-scope button.active{border:2px solid #2563eb;background:#eff6ff}.surebet-filters{margin:10px 0}.surebet-filters select{padding:8px;border-radius:8px;border:1px solid #ccd6e5}.surebet-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0}.surebet-opportunity{border:1px solid #dfe5ee;border-radius:14px;padding:16px;margin:14px 0;background:#fff}.opp-head{display:flex;justify-content:space-between;gap:15px}.opp-head h3{margin:5px 0;font-size:20px}.margin-box{background:#ecfdf5;border-radius:10px;padding:10px;text-align:center;min-width:120px}.margin-box small{display:block;font-size:10px}.margin-box strong{font-size:23px;color:#0f8a62}.odds-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.odd-card{border:1px solid #e5eaf1;border-radius:10px;padding:11px;background:#f8fafc}.odd-card span,.odd-card small{display:block}.odd-card b{display:block;font-size:23px;margin:3px 0}.calc-box{border-top:1px solid #e5eaf1;padding-top:12px}.calc-title{font-size:12px;font-weight:900;margin:10px 0 7px}.calc-table,.stake-table{margin-bottom:10px}.calc-table th,.calc-table td,.stake-table th,.stake-table td{font-size:12px;padding:7px}.opp-footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px;font-size:12px}.empty-surebet{padding:20px;border:1px dashed #ccd6e5;border-radius:12px;text-align:center}@media(max-width:700px){.surebet-summary,.odds-grid{grid-template-columns:1fr}.opp-head,.opp-footer{flex-direction:column;align-items:stretch}}')
    return HTMLResponse(html)
